/* Home building and Profile open the same small, illustrated settings room. */
function profileRoomArt(type){const base='<ellipse cx="90" cy="142" rx="68" ry="12" fill="#4f4a3830"/>';const art={
 portrait:`<path d="M35 17h110v120H35Z" fill="#9b6944" stroke="#e3b76f" stroke-width="9"/><path d="M45 27h90v100H45Z" fill="#e9d9ab"/><text x="90" y="99" text-anchor="middle" font-size="60">${avatarAnimals[profilePrefs().avatar]||'🦊'}</text><path d="M58 128h64v13H58Z" fill="#d6a75e"/>`,
 farm:'<path d="M36 22v118m108-118v118" stroke="#795a3a" stroke-width="7"/><path d="M20 39h140v70H20Z" fill="#d8ac68" stroke="#a57b47" stroke-width="5"/><path d="M27 44h126" stroke="#f4d699" stroke-width="3"/><path d="M64 92l26-26 26 26v25H64Z" fill="#faf0ce"/><path d="M60 92l30-32 30 32" fill="none" stroke="#73905a" stroke-width="9"/><path d="M85 103h12v14H85Z" fill="#809775"/>',
 finance:'<path d="M38 40l90-14 27 17v99l-94 11-23-15Z" fill="#677d78"/><path d="M38 40l94 8v96l-94-6Z" fill="#91a49a" stroke="#d3d4b8" stroke-width="4"/><rect x="51" y="54" width="67" height="70" rx="8" fill="#56736c" stroke="#c0c6ac" stroke-width="4"/><circle cx="85" cy="88" r="20" fill="#bbbc91"/><path d="M85 70v36m-18-18h36" stroke="#e8deae" stroke-width="5"/><g fill="#f3cf70" stroke="#bd9848" stroke-width="2"><ellipse cx="135" cy="137" rx="20" ry="7"/><ellipse cx="135" cy="131" rx="20" ry="7"/><ellipse cx="135" cy="125" rx="20" ry="7"/></g>',
 tasks:'<path d="M21 103h138v18H21Z" fill="#af7c4d"/><path d="M29 121v25m122-25v25" stroke="#755538" stroke-width="10"/><path d="M58 45h68v64H58Z" fill="#d1a367" stroke="#a77d4b" stroke-width="5"/><path d="M68 54h49v47H68Z" fill="#fff4cf"/><path d="M75 67h32m-32 12h32m-32 12h22" stroke="#b7bf95" stroke-width="4"/><path d="M42 103l13-52" stroke="#4f7560" stroke-width="5"/><path d="M38 101h18v12H38Z" fill="#7fa58b"/>',
 theme:'<path d="M47 67l17-46h52l18 46Z" fill="#f7d991" stroke="#c5a460" stroke-width="4"/><path d="M90 68v60" stroke="#7f7357" stroke-width="8"/><ellipse cx="90" cy="131" rx="35" ry="9" fill="#8a8569"/><ellipse class="profile-lamp-glow" cx="90" cy="75" rx="59" ry="25" fill="#ffe49e" opacity=".35"/><path d="M123 70v30" stroke="#bca16c" stroke-width="2"/><circle cx="123" cy="102" r="5" fill="#d4a55e"/>',
 account:'<path d="M34 26h112v115H34Z" fill="#ae8353" stroke="#785c3e" stroke-width="5"/><path d="M43 34h43v97H43Zm51 0h43v97H94Z" fill="#c49c65" stroke="#ddbd85" stroke-width="3"/><circle cx="78" cy="85" r="4" fill="#f8dfa1"/><circle cx="103" cy="85" r="4" fill="#f8dfa1"/><path d="M42 141v9m96-9v9" stroke="#745a3d" stroke-width="8"/><rect x="71" y="68" width="38" height="34" rx="7" fill="#e3ca88"/><path d="M80 68v-9a10 10 0 0 1 20 0v9" fill="none" stroke="#e3ca88" stroke-width="6"/><circle cx="90" cy="83" r="4" fill="#947a4a"/>',
 privacy:'<path d="M25 27h130v106H25Z" fill="#926c44" stroke="#d9b47a" stroke-width="6"/><path d="M34 36h112v87H34Z" fill="#afc98b"/><path d="M104 36q-40 24-20 42t-18 45" fill="none" stroke="#81b4b2" stroke-width="12"/><path d="M34 72q56-25 112 22" fill="none" stroke="#f1ddb1" stroke-width="8"/><path d="M108 65l15-15 15 15v25h-30Z" fill="#fff0bd"/><path d="M105 65l18-18 18 18" fill="none" stroke="#9e7152" stroke-width="6"/>'};return `<svg viewBox="0 0 180 165" aria-hidden="true">${base}${art[type]}</svg>`}
function profileRoomBackground(){return `<svg class="profile-room-background" viewBox="0 0 1200 740" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="room-wall" x2="0" y2="1"><stop stop-color="#e9dfb9"/><stop offset="1" stop-color="#d2c39d"/></linearGradient><linearGradient id="room-floor" x2="0" y2="1"><stop stop-color="#b99162"/><stop offset="1" stop-color="#d1ad77"/></linearGradient><pattern id="room-boards" width="160" height="65" patternUnits="userSpaceOnUse"><path d="M0 0h160v65H0Z" fill="none" stroke="#8f7049" stroke-width="2" opacity=".3"/></pattern></defs><path d="M0 0h1200v490H0Z" fill="url(#room-wall)"/><path d="M0 0h52v490H0Zm1148 0h52v490h-52Z" fill="#bca37b"/><path d="M0 478h1200v16H0Z" fill="#93754f"/><path d="M0 494h1200v246H0Z" fill="url(#room-floor)"/><path d="M0 494h1200v246H0Z" fill="url(#room-boards)"/><path d="M60 0v477m1080-477v477" stroke="#f8edce" stroke-width="4" opacity=".5"/><rect x="470" y="90" width="260" height="220" rx="10" fill="#937d56"/><rect x="483" y="103" width="234" height="193" rx="5" fill="#bfdbd2"/><path d="M483 233q60-90 123-25t111-5v93H483Z" fill="#90b379"/><path d="M483 257q100-59 234 10v29H483Z" fill="#6d995e"/><circle cx="671" cy="146" r="23" fill="#fff3bf"/><path d="M600 103v193m-117-91h234" stroke="#f1e5c2" stroke-width="9"/><path d="M456 82h288v20H456Z" fill="#806b4d"/><path d="M460 102v211l35-13-5-198m250 0v211l-35-13 5-198" fill="#a7b993"/><ellipse cx="625" cy="632" rx="310" ry="66" fill="#b7ba8b" stroke="#eee0af" stroke-width="9"/><ellipse cx="625" cy="632" rx="272" ry="48" fill="none" stroke="#e8d7a2" stroke-width="3" opacity=".6"/><path d="M1010 425v56h55v-56Z" fill="#bc9060"/><path d="M1035 430q-58-30-39-66q35 1 39 48q-5-67 31-73q28 36-31 91" fill="#7e9e68"/></svg>`}
const profilePageBeforeRoom=userProfilePage;
userProfilePage=function(){if(!account)return profilePageBeforeRoom();const prefs=profilePrefs();return `<section class="profile-room" aria-label="Комната хозяина">${profileRoomBackground()}<div class="profile-room-title"><small>ВАШ ДОМ · ВСЁ ПОД РУКОЙ</small><h1>Комната хозяина</h1></div>${[['portrait','Ник и аватар','profileRoomIdentity()'],['farm','Название хозяйства','nameMyFarm()'],['finance','Мои финансы',"location.hash='wallet'"],['tasks','Мои дела','profileRoomTasks()'],['theme','Свет и тема','profileRoomTheme()'],['account','Аккаунт и данные','profileRoomAccount()'],['privacy',ownFarm?.visible?'Хозяйство видно':'Хозяйство скрыто','profileRoomVisibility()']].map(([type,title,action])=>`<button class="profile-room-object room-object-${type}" onclick="${action}">${profileRoomArt(type)}<b>${title}</b></button>`).join('')}<a class="profile-room-exit" href="#home">← Во двор</a></section>`};
function profileRoomIdentity(){formAsync('Ваш игровой ник',`<div class="profile-room-avatar">${avatarAnimals[profilePrefs().avatar]||'🦊'}</div><label>Игровой ник<input name="name" minlength="2" maxlength="60" required value="${esc(account.name)}" autocomplete="nickname"></label><button class="btn">Сохранить ник</button><button type="button" class="btn light" onclick="profileRoomAvatars()">Выбрать аватарку</button>`,async f=>{const data=await api('profile-save',{name:f.get('name')});account=data.user;if(cloud)cloud.user=data.user;modal.close();toast('Игровой ник сохранён')})}
function profileRoomAvatars(){modalForm('Кто вы сегодня?',`<div class="avatar-picker room-avatar-picker">${Object.entries(avatarAnimals).map(([id,emoji])=>`<button type="button" aria-label="${avatarNames[id]}" aria-pressed="${(profilePrefs().avatar||'fox')===id}" onclick="setProfilePref('avatar','${id}');modal.close();render()">${emoji}</button>`).join('')}</div><p class="profile-room-note">Аватар сохраняется на этом устройстве.</p>`,()=>{})}
nameMyFarm=function(){if(!account)return profile();farmNameOffered=true;formAsync('Название хозяйства',`<label>Как назовём хозяйство?<input name="name" required minlength="2" maxlength="60" value="${esc(ownFarm?.name||'')}" placeholder="Например, Мятный двор"></label><button class="btn">Сохранить название</button>`,async f=>{const fresh=!ownFarm;await api('my-farm',{name:f.get('name')});if(fresh)await api('my-farm',{visible:false});await loadFarmIdentity();modal.close();toast('Название хозяйства сохранено')})};
function profileRoomTasks(){modalForm('Мои дела',`<div class="room-menu-links"><a href="#orders" onclick="modal.close()">👩‍🌾 Работы садовника <span>›</span></a><a href="#lifecycle" onclick="modal.close()">🚚 Доставка и подписки <span>›</span></a><a href="#notifications" onclick="modal.close()">🔔 Уведомления <span>›</span></a></div>`,()=>{})}
function profileRoomTheme(){modalForm('Свет в вашем доме',`<div class="room-theme-choice"><button type="button" onclick="setProfilePref('theme','light');modal.close();render()"><span>☀️</span>Светлая</button><button type="button" onclick="setProfilePref('theme','dark');modal.close();render()"><span>🌙</span>Тёмная</button></div><label class="profile-toggle"><input type="checkbox" ${profilePrefs().motion?'checked':''} onchange="setProfilePref('motion',this.checked)"> Меньше анимации</label>`,()=>{})}
function profileRoomAccount(){modalForm('Аккаунт и данные',`<p class="profile-room-note">${esc(account.login)}</p><div class="room-menu-links"><button type="button" onclick="changeMyPassword()">🔑 Сменить пароль <span>›</span></button><button type="button" onclick="exportData()">📄 Скачать мои записи <span>›</span></button><button type="button" onclick="closeOtherSessions()">📱 Выйти на всех устройствах <span>›</span></button>${account.role==='admin'?'<a href="#farmer" onclick="modal.close()">🌿 Управление фермой <span>›</span></a>':''}<button type="button" onclick="profileRoomLogout()">🚪 Выйти из аккаунта <span>›</span></button></div>`,()=>{})}
function profileRoomLogout(){formAsync('Выйти из аккаунта?','<button class="btn">Выйти</button>',async()=>{await api('logout',{});location.reload()})}
async function profileRoomVisibility(){if(!ownFarm){nameMyFarm();return}const visible=!!ownFarm.visible;formAsync(visible?'Скрыть хозяйство?':'Показать хозяйство?',`<div class="profile-room-avatar">${visible?'🌳':'🗺️'}</div><p>${visible?'Хозяйство исчезнет с карты. Все ваши товары также пропадут с рынка и станут недоступны для новых покупок. Уже оформленные заказы сохранятся.':'Хозяйство появится на карте, а действующие товары снова станут доступны на рынке при активном складе и действующем сроке хранения.'}</p><p class="profile-room-note">Объявления сохранятся у вас. Видимость можно изменить в любой момент.</p><button class="btn">${visible?'Скрыть хозяйство и товары':'Показать хозяйство и товары'}</button>`,async()=>{await api('my-farm',{visible:!visible});await loadFarmIdentity();lifeData=null;modal.close();toast(visible?'Хозяйство и товары скрыты':'Хозяйство снова видно')})}
farmViews.add(()=>{document.body.classList.toggle('profile-room-screen',location.hash==='#settings'&&!!account);if(location.hash==='#settings'&&account){document.querySelectorAll('#app>.panel,#app>.actions,#app>.basket-link').forEach(el=>el.remove())}});
